TLM.f("Sancti/08-11",{"officium":"Ss. Tiburtii et Susannæ Virginum et Martyrum","rule":["Gloria"],"fallback":"Commune/C3b","from":{"Introitus":"Commune/C3b","Graduale":"Commune/C3b","Tractus":"Commune/C3b","Evangelium":"Commune/C3b","Offertorium":"Commune/C3b","Communio":"Commune/C3b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:39"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salus autem justórum a Dómino: et protéctor eórum est in témpore tribulatiónis."}],"Oratio":[{"k":"text","la":"Sanctórum Martyrum tuórum Tiburtii et Susánnæ nos, Dómine, fóveant continuáta præsídia: quia non désinis propítius intuéri; quos tálibus auxíliis concésseris adjuvári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 11:33-39"},{"k":"text","la":"Fratres: Sancti per fidem vicérunt regna, operáti sunt justítiam, adépti sunt repromissiónes, obturavérunt ora leónum, exstinxérunt ímpetum ignis, effugérunt áciem gládii, convaluérunt de infirmitáte, fortes facti sunt in bello, castra vertérunt exterórum: accepérunt mulíeres de resurrectióne mórtuos suos: álii autem distenti sunt, non suscipiéntes redemptiónem, ut meliórem invenírent resurrectiónem: álii vero ludíbria et vérbera expérti, ínsuper et víncula et cárceres: lapidáti sunt, secti sunt, tentáti sunt, in occisióne gládii mórtui sunt: circuiérunt in melótis, in péllibus caprínis, egéntes, angustiáti, afflícti: quibus dignus non erat mundus: in solitudínibus errántes, in móntibus et spelúncis et in cavérnis terræ. Et hi omnes testimónio fídei probáti, invénti sunt in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvábit.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Sap 3:1-3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiae: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."}],"Secreta":[{"k":"text","la":"Adésto, Dómine, précibus pópuli tui, adésto munéribus: ut, quæ sacris sunt obláta mystériis, tuórum tibi pláceant intercessióne Sanctórum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 10:27"},{"k":"text","la":"Quod dico vobis in ténebris, dícite in lúmine, dicit Dóminus: et quod in aure audítis, prædicáte super tecta."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, pignus redemptiónis ætérnæ: quod sit nobis, quǽsumus, interveniéntibus sanctis Martýribus tuis, vitæ præséntis auxílium páriter et futúræ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2b474b8413482a17":{"t":"<i>Pomolimo se</i>.\nNeka nas pomogne, Gospodine, neprestana zaštita svetih mučenika tvojih Tiburcija i Suzane, jer ne prestaješ milostivo gledati na one koje na takav način pomažeš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8261993f4cb99033":{"t":"Milostiv budi, Gospodine, molitvama svoga naroda, milostiv budi darovima, da ti se po zagovoru svetih svidi ono što u svetim tajnama prikazujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5c907a5f8b318cc9":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, zalog vječnog otkupljenja, koji neka nam bude po zagovoru svetih mučenika tvojih pomoć za sadašnji i budući život.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
